    private static boolean isShadow(int itemId)
    {
        return itemId == TUMEKENS_SHADOW || itemId == TUMEKENS_SHADOW_UNCHARGED;
    }

    private int drawHoldTicks()
    {
        ItemStats stats = itemManager.getItemStats(getEquippedWeaponItemId());
        if (stats != null && stats.getEquipment() != null)
            return Math.max(5, stats.getEquipment().getAspeed() + 1);
        return 7;
    }

    private WeaponGroup detectWeaponGroup(int id)
    {
        if (id < 0) return WeaponGroup.NONE;
        if (isShadow(id)) return WeaponGroup.STAFF;
        if (id == TWISTED_BOW) return WeaponGroup.BOW;
        if (id == SOULREAPER_AXE) return WeaponGroup.TWO_HANDED;
        String name = itemManager.getItemComposition(id).getName().toLowerCase(Locale.ROOT);
        // Crossbows need their own hip preset even when equipment metadata
        // describes the crossbow as two-handed.
        if (name.contains("crossbow")) return WeaponGroup.CROSSBOW;
        if (name.contains("wand")) return WeaponGroup.WAND;
        if (name.contains("staff") || name.contains("trident") || name.contains("sceptre")
            || name.contains("scepter") || name.contains("eye of ayak"))
            return WeaponGroup.STAFF;
        if (name.contains("bow")) return WeaponGroup.BOW;
        ItemStats stats = itemManager.getItemStats(id);
        if (stats != null && stats.getEquipment() != null && stats.getEquipment().isTwoHanded())
            return WeaponGroup.TWO_HANDED;
        if (stats != null && stats.getEquipment() != null && stats.getEquipment().getSlot() == 3)
            return WeaponGroup.ONE_HANDED;
        return WeaponGroup.NONE;
    }

    private Placement itemOverride(int itemId)
    {
        for (String entry : config.itemPlacements().split(";"))
        {
            String[] parts = entry.trim().split(":");
            if (parts.length != 2) continue;
            try
            {
                if (Integer.parseInt(parts[0].trim()) != itemId) continue;
                String[] values = parts[1].split(",");
                if (values.length != 7) continue;
                int[] v = new int[7];
                for (int i = 0; i < 7; i++) v[i] = Integer.parseInt(values[i].trim());
                if (v[6] < 25 || v[6] > 200) continue;
                boolean valid = true;
                for (int i = 0; i < 6; i++)
                    if (v[i] < (i < 3 ? -200 : -180) || v[i] > (i < 3 ? 200 : 180)) valid = false;
                if (valid) return new Placement(v[0], v[1], v[2], v[3], v[4], v[5], v[6]);
            }
            catch (NumberFormatException ignored) { /* Use the category preset. */ }
        }
        return null;
    }

    private Placement placementFor(int itemId)
    {
        Placement override = itemOverride(itemId);
        if (override != null) return override;
        return categoryPlacement(itemId);
    }

    private Placement placementForOffHand(int itemId)
    {
        Placement override = itemOverride(itemId);
        return override != null ? override : offHandPlacement(itemId);
    }

    int[] defaultPlacement(int itemId)
    {
        ItemStats stats = itemManager.getItemStats(itemId);
        boolean offHand = itemId == getEquippedShieldItemId()
            || stats != null && stats.getEquipment() != null && stats.getEquipment().getSlot() == 5;
        Placement p = offHand ? offHandPlacement(itemId) : categoryPlacement(itemId);
        return new int[]{p.sideways, p.height, p.forward, p.pitch, p.yaw, p.roll, p.scale};
    }

    private Placement offHandPlacement(int itemId)
    {
        String name = itemManager.getItemComposition(itemId).getName().toLowerCase(Locale.ROOT);
        // Some shields have a game-specific name without "shield" in it.
        if (name.contains("shield") || name.contains("ward")
            || name.contains("buckler") || name.contains("toktz-ket-xil"))
            return shieldPlacement();
        return new Placement(config.offHandHipSideways(), config.offHandHipHeight(),
            config.offHandHipForward(), config.offHandHipPitch(), config.offHandHipYaw(),
            config.offHandHipRoll(), config.offHandHipScale());
    }

    private Placement shieldPlacement()
    {
        return new Placement(config.shieldSideways(), config.shieldHeight(),
            config.shieldForward(), config.shieldPitch(), config.shieldYaw(),
            config.shieldRoll(), config.shieldScale());
    }

    private Placement categoryPlacement(int itemId)
    {
        if (detectWeaponGroup(itemId) == WeaponGroup.CROSSBOW)
            return new Placement(config.crossbowSideways(), config.crossbowHeight(),
                config.crossbowForward(), config.crossbowPitch(), config.crossbowYaw(),
                config.crossbowRoll(), config.crossbowScale());
        if (detectWeaponGroup(itemId) == WeaponGroup.ONE_HANDED)
            return new Placement(config.oneHandSideways(), config.oneHandHeight(),
                config.oneHandForward(), config.oneHandPitch(), config.oneHandYaw(),
                config.oneHandRoll(), config.oneHandScale());
        if (detectWeaponGroup(itemId) == WeaponGroup.WAND)
            return new Placement(config.wandSideways(), config.wandHeight(),
                config.wandForward(), config.wandPitch(), config.wandYaw(),
                config.wandRoll(), config.wandScale());
        if (detectWeaponGroup(itemId) == WeaponGroup.STAFF)
        {
            return new Placement(config.shadowSideways(), config.shadowHeight(),
                config.shadowForward(), config.shadowPitch(), config.shadowYaw(),
                config.shadowRoll(), config.shadowScale());
        }
        if (detectWeaponGroup(itemId) == WeaponGroup.BOW)
        {
            return new Placement(config.twistedBowSideways(), config.twistedBowHeight(),
                config.twistedBowForward(), config.twistedBowPitch(), config.twistedBowYaw(),
                config.twistedBowRoll(), config.twistedBowScale());
        }
        return new Placement(config.sideways(), config.height(), config.forward(),
            config.pitch(), config.yaw(), config.roll(), config.scale());
    }

    private static final class Placement
    {
        private final int sideways;
        private final int height;
        private final int forward;
        private final int pitch;
        private final int yaw;
        private final int roll;
        private final int scale;

        private Placement(int sideways, int height, int forward, int pitch,
            int yaw, int roll, int scale)
        {
            this.sideways = sideways;
            this.height = height;
            this.forward = forward;
            this.pitch = pitch;
            this.yaw = yaw;
            this.roll = roll;
            this.scale = scale;
        }
    }

    /** RuneLite objects do not inherit an actor's animated skeleton. Build a
     * frame from upper torso vertices so gear follows the torso's pitch, roll
     * and sway while walking and running.
     */
    private void positionOnAnimatedTorso(Player player)
    {
        LocalPoint playerPoint = player.getLocalLocation();
        Model playerModel = player.getModel();
        if (playerPoint == null || playerModel == null
            || holsteredWeapon == null && holsteredShield == null)
        {
            return;
        }

        boolean idle = player.getPoseAnimation() == player.getIdlePoseAnimation()
            && player.getAnimation() == -1;
        if (torsoRig == null || torsoRig.vertexCount != playerModel.getVerticesCount()
            || (idle && !torsoRigCapturedWhileIdle))
        {
            torsoRig = null;
            TorsoRig candidate = TorsoRig.capture(playerModel);
            if (candidate != null)
            {
                torsoRig = candidate;
                torsoRigCapturedWhileIdle = idle;
            }
        }

        int orientation = player.getCurrentOrientation();
        int plane = player.getWorldLocation().getPlane();
        if (holsteredWeapon != null)
            positionItem(playerModel, holsteredWeapon, holsteredModel, baseWeaponX,
                baseWeaponY, baseWeaponZ, playerPoint, plane, orientation);
        if (holsteredShield != null)
            positionItem(playerModel, holsteredShield, holsteredShieldModel, baseShieldX,
                baseShieldY, baseShieldZ, playerPoint, plane, orientation);
    }

    private void positionItem(Model playerModel, RuneLiteObject object, Model itemModel,
        float[] baseX, float[] baseY, float[] baseZ, LocalPoint location,
        int plane, int orientation)
    {
        if (torsoRig != null && itemModel != null && baseX != null)
        {
            torsoRig.apply(playerModel, itemModel, baseX, baseY, baseZ);
            itemModel.calculateBoundsCylinder();
            object.setModel(itemModel);
        }
        object.setLocation(location, plane);
        object.setZ(Perspective.getTileHeight(client, location, plane));
        object.setOrientation(orientation);
    }

    private static final class TorsoRig
    {
        private final int vertexCount;
        private final int[] torso;
        private final int[] left;
        private final int[] right;
        private final int[] top;
        private final int[] bottom;
        private final Vec3 referenceAnchor;
        private final Frame referenceFrame;

        private TorsoRig(int vertexCount, int[] torso, int[] left, int[] right,
            int[] top, int[] bottom, Vec3 referenceAnchor, Frame referenceFrame)
        {
            this.vertexCount = vertexCount;
            this.torso = torso;
            this.left = left;
            this.right = right;
            this.top = top;
            this.bottom = bottom;
            this.referenceAnchor = referenceAnchor;
            this.referenceFrame = referenceFrame;
        }

        private static TorsoRig capture(Model model)
        {
            int count = model.getVerticesCount();
            if (count == 0)
            {
                return null;
            }
            float[] x = model.getVerticesX();
            float[] y = model.getVerticesY();
            float minX = Float.MAX_VALUE, maxX = -Float.MAX_VALUE;
            float minY = Float.MAX_VALUE, maxY = -Float.MAX_VALUE;
            for (int i = 0; i < count; i++)
            {
                minX = Math.min(minX, x[i]); maxX = Math.max(maxX, x[i]);
                minY = Math.min(minY, y[i]); maxY = Math.max(maxY, y[i]);
            }

            double centreX = (minX + maxX) * .5;
            double halfWidth = Math.max(12.0, (maxX - minX) * .28);
            double upperStart = minY + (maxY - minY) * .16;
            double upperEnd = minY + (maxY - minY) * .56;
            List<Integer> torsoList = new ArrayList<>();
            for (int i = 0; i < count; i++)
            {
                if (y[i] >= upperStart && y[i] <= upperEnd
                    && Math.abs(x[i] - centreX) <= halfWidth)
                {
                    torsoList.add(i);
                }
            }
            if (torsoList.size() < 12)
            {
                return null;
            }

            int[] torso = toArray(torsoList);
            Vec3 anchor = average(model, torso);
            List<Integer> leftList = new ArrayList<>();
            List<Integer> rightList = new ArrayList<>();
            List<Integer> topList = new ArrayList<>();
            List<Integer> bottomList = new ArrayList<>();
            for (int index : torso)
            {
                if (x[index] < anchor.x) leftList.add(index);
                else rightList.add(index);
                if (y[index] < anchor.y) topList.add(index);
                else bottomList.add(index);
            }
            if (leftList.size() < 3 || rightList.size() < 3
                || topList.size() < 3 || bottomList.size() < 3)
            {
                return null;
            }
            int[] left = toArray(leftList);
            int[] right = toArray(rightList);
            int[] top = toArray(topList);
            int[] bottom = toArray(bottomList);
            Frame frame = frame(model, left, right, top, bottom);
            if (frame == null)
            {
                return null;
            }
            return new TorsoRig(count, torso, left, right, top, bottom, anchor, frame);
        }

        private void apply(Model playerModel, Model weaponModel,
            float[] baseX, float[] baseY, float[] baseZ)
        {
            Frame currentFrame = frame(playerModel, left, right, top, bottom);
            if (currentFrame == null)
            {
                return;
            }
            Vec3 currentAnchor = average(playerModel, torso);
            float[] x = weaponModel.getVerticesX();
            float[] y = weaponModel.getVerticesY();
            float[] z = weaponModel.getVerticesZ();
            int count = Math.min(weaponModel.getVerticesCount(), baseX.length);
            for (int i = 0; i < count; i++)
            {
                Vec3 offset = new Vec3(baseX[i] - referenceAnchor.x,
                    baseY[i] - referenceAnchor.y, baseZ[i] - referenceAnchor.z);
                double alongRight = offset.dot(referenceFrame.right);
                double alongUp = offset.dot(referenceFrame.up);
                double alongForward = offset.dot(referenceFrame.forward);
                Vec3 transformed = currentAnchor
                    .add(currentFrame.right.scale(alongRight))
                    .add(currentFrame.up.scale(alongUp))
                    .add(currentFrame.forward.scale(alongForward));
                x[i] = (float) transformed.x;
                y[i] = (float) transformed.y;
                z[i] = (float) transformed.z;
            }
        }

        private static Frame frame(Model model, int[] left, int[] right,
            int[] top, int[] bottom)
        {
            Vec3 rightAxis = average(model, right).subtract(average(model, left)).normalise();
            Vec3 rawUp = average(model, top).subtract(average(model, bottom));
            Vec3 upAxis = rawUp.subtract(rightAxis.scale(rawUp.dot(rightAxis))).normalise();
            if (!rightAxis.valid() || !upAxis.valid())
            {
                return null;
            }
            Vec3 forwardAxis = upAxis.cross(rightAxis).normalise();
            if (!forwardAxis.valid())
            {
                return null;
            }
            // Re-orthogonalise so animation deformation cannot stretch the axe.
            upAxis = rightAxis.cross(forwardAxis).normalise();
            return new Frame(rightAxis, upAxis, forwardAxis);
        }

        private static Vec3 average(Model model, int[] indices)
        {
            float[] x = model.getVerticesX();
            float[] y = model.getVerticesY();
            float[] z = model.getVerticesZ();
            double sx = 0, sy = 0, sz = 0;
            for (int index : indices)
            {
                sx += x[index]; sy += y[index]; sz += z[index];
            }
            return new Vec3(sx / indices.length, sy / indices.length, sz / indices.length);
        }

        private static int[] toArray(List<Integer> values)
        {
            int[] result = new int[values.size()];
            for (int i = 0; i < values.size(); i++) result[i] = values.get(i);
            return result;
        }
    }

    private static final class Frame
    {
        private final Vec3 right;
        private final Vec3 up;
        private final Vec3 forward;

        private Frame(Vec3 right, Vec3 up, Vec3 forward)
        {
            this.right = right;
            this.up = up;
            this.forward = forward;
        }
    }

    private static final class Vec3
    {
        private final double x;
        private final double y;
        private final double z;

        private Vec3(double x, double y, double z)
        {
            this.x = x; this.y = y; this.z = z;
        }

        private Vec3 add(Vec3 other) { return new Vec3(x + other.x, y + other.y, z + other.z); }
        private Vec3 subtract(Vec3 other) { return new Vec3(x - other.x, y - other.y, z - other.z); }
        private Vec3 scale(double amount) { return new Vec3(x * amount, y * amount, z * amount); }
        private double dot(Vec3 other) { return x * other.x + y * other.y + z * other.z; }
        private Vec3 cross(Vec3 other)
        {
            return new Vec3(y * other.z - z * other.y,
                z * other.x - x * other.z, x * other.y - y * other.x);
        }
        private Vec3 normalise()
        {
            double length = Math.sqrt(dot(this));
            return length < .0001 ? new Vec3(Double.NaN, Double.NaN, Double.NaN)
                : scale(1.0 / length);
        }
        private boolean valid()
        {
            return Double.isFinite(x) && Double.isFinite(y) && Double.isFinite(z);
        }
    }

    private void destroyObject()
    {
        if (holsteredWeapon != null)
        {
            holsteredWeapon.setActive(false);
            holsteredWeapon = null;
        }
        holsteredModel = null;
        baseWeaponX = null;
        baseWeaponY = null;
        baseWeaponZ = null;
        if (holsteredShield == null)
        {
            torsoRig = null;
            torsoRigCapturedWhileIdle = false;
        }
        builtWeaponItemId = -1;
    }

    private void destroyShield()
    {
        if (holsteredShield != null)
        {
            holsteredShield.setActive(false);
            holsteredShield = null;
        }
        holsteredShieldModel = null;
        baseShieldX = null;
        baseShieldY = null;
        baseShieldZ = null;
        if (holsteredWeapon == null)
        {
            torsoRig = null;
            torsoRigCapturedWhileIdle = false;
        }
        builtShieldItemId = -1;
    }
}

package com.rapidursa.holster.appearance;

import java.util.LinkedHashMap;
import java.util.Map;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;

/**
 * Parses item, kit and spotanim definitions straight out of the client's own
 * loaded cache ({@link Client#getIndexConfig()}), so the plugin needs no
 * offline dumps: Hub users get the full outfit catalogue and graphic
 * repository the moment the client is running.
 *
 * <p>The opcode logic is a faithful port of runelite-cache's ItemLoader,
 * KitLoader and SpotAnimLoader, transcribed from the library's bytecode and
 * validated in game by diffing every entry against the offline dumper's
 * output ({@code ::follower cachecheck}). Output shapes mirror the dump files
 * exactly, defaults included, so the repositories cannot tell the difference.
 *
 * <p>Every definition parses independently: a malformed or future-format
 * entry is skipped with a note rather than failing the whole catalogue.
 */
@Slf4j
public final class LiveCacheParser
{
	/** Config-index archive ids (net.runelite.cache.ConfigType). */
	private static final int CONFIG_IDENTKIT = 3;
	private static final int CONFIG_ITEM = 10;
	private static final int CONFIG_SEQUENCE = 12;
	private static final int CONFIG_SPOTANIM = 13;

	private LiveCacheParser()
	{
	}

	/**
	 * The id of every animation the cache holds.
	 *
	 * <p>Only the archive's file list is read, never the definitions: an id is
	 * either in there or it is not, which is the whole question a validity
	 * check asks. Used by {@code ::follower stanceaudit} to prove that no
	 * stance names an animation that does not exist.
	 */
	public static java.util.Set<Integer> sequenceIds(Client client)
	{
		IndexDataBase configs = client.getIndexConfig();
		java.util.Set<Integer> ids = new java.util.HashSet<>();
		if (configs == null)
		{
			return ids;
		}
		for (int id : configs.getFileIds(CONFIG_SEQUENCE))
		{
			ids.add(id);
		}
		return ids;
	}

	/** Wearable items keyed by id, matching equipment-models.json's items map. */
	public static Map<String, ModelRepository.Entry> parseItems(Client client)
	{
		IndexDataBase configs = client.getIndexConfig();
		Map<String, ModelRepository.Entry> items = new LinkedHashMap<>();
		if (configs == null)
		{
			return items;
		}
		int failures = 0;
		for (int id : configs.getFileIds(CONFIG_ITEM))
		{
			byte[] data = configs.loadData(CONFIG_ITEM, id);
			if (data == null)
			{
				continue;
			}
			try
			{
				ModelRepository.Entry entry = decodeItem(data);
				if (entry != null)
				{
					items.put(Integer.toString(id), entry);
				}
			}
			catch (RuntimeException e)
			{
				if (failures++ == 0)
				{
					log.warn("Item {} failed to parse (further failures counted silently)", id, e);
				}
			}
		}
		if (failures > 0)
		{
			log.warn("{} item definitions failed to parse", failures);
		}
		return items;
	}

	/** Body kits keyed by id, matching equipment-models.json's kits map. */
	public static Map<String, ModelRepository.Entry> parseKits(Client client)
	{
		return parseKits(client, null);
	}

	/**
	 * @param nonSelectableOut when non-null, receives the ids of kits flagged
	 * non-selectable - the styles character creation does not offer, which is
	 * how the NPC-only and unreleased extras are told apart from real player
	 * styles. Collected on the side so {@link ModelRepository.Entry} keeps the
	 * dump file's exact shape and {@code ::follower cachecheck} stays honest.
	 */
	public static Map<String, ModelRepository.Entry> parseKits(Client client,
		java.util.Set<Integer> nonSelectableOut)
	{
		IndexDataBase configs = client.getIndexConfig();
		Map<String, ModelRepository.Entry> kits = new LinkedHashMap<>();
		if (configs == null)
		{
			return kits;
		}
		for (int id : configs.getFileIds(CONFIG_IDENTKIT))
		{
			byte[] data = configs.loadData(CONFIG_IDENTKIT, id);
			if (data == null)
			{
				continue;
			}
			try
			{
				boolean[] nonSelectable = new boolean[1];
				ModelRepository.Entry entry = decodeKit(data, nonSelectable);
				if (entry != null)
				{
					kits.put(Integer.toString(id), entry);
					if (nonSelectable[0] && nonSelectableOut != null)
					{
						nonSelectableOut.add(id);
					}
				}
			}
			catch (RuntimeException e)
			{
				log.debug("Kit {} failed to parse", id, e);
			}
		}
		return kits;
	}

	/** Spotanims keyed by id, matching spotanims.json. */
	public static Map<String, SpotAnimRepository.Entry> parseSpotAnims(Client client)
	{
		IndexDataBase configs = client.getIndexConfig();
		Map<String, SpotAnimRepository.Entry> spotAnims = new LinkedHashMap<>();
		if (configs == null)
		{
			return spotAnims;
		}
		int failures = 0;
		for (int id : configs.getFileIds(CONFIG_SPOTANIM))
		{
			byte[] data = configs.loadData(CONFIG_SPOTANIM, id);
			if (data == null)
			{
				continue;
			}
			try
			{
				SpotAnimRepository.Entry entry = decodeSpotAnim(data);
				if (entry != null)
				{
					spotAnims.put(Integer.toString(id), entry);
				}
			}
			catch (RuntimeException e)
			{
				if (failures++ == 0)
				{
					log.warn("Spotanim {} failed to parse: {}", id, e.getMessage());
				}
			}
		}
		if (failures > 0)
		{
			log.warn("{} spotanim definitions failed to parse", failures);
		}
		return spotAnims;
	}

	// ------------------------------------------------------------------ items

	/**
	 * ItemLoader's opcode walk. Only the fields the follower needs are kept,
	 * but EVERY opcode must be consumed at its exact width or the stream
	 * desynchronises and the rest of the definition parses as garbage.
	 */
	static ModelRepository.Entry decodeItem(byte[] data)
	{
		Buffer in = new Buffer(data);
		// The cache's convention for an unnamed item is the literal string
		// "null" (the definition's constructor default), and the dumper
		// preserved it - so the live parse must too.
		String name = "null";
		int maleModel0 = -1;
		int maleModel1 = -1;
		int maleModel2 = -1;
		int femaleModel0 = -1;
		int femaleModel1 = -1;
		int femaleModel2 = -1;
		int maleOffset = 0;
		int femaleOffset = 0;
		int maleHead = -1;
		int maleHead2 = -1;
		int femaleHead = -1;
		int femaleHead2 = -1;
		int wearPos1 = -1;
		int wearPos2 = -1;
		int wearPos3 = -1;
		short[] colorFind = null;
		short[] colorReplace = null;
		short[] textureFind = null;
		short[] textureReplace = null;

		for (int opcode = in.readUnsignedByte(); opcode != 0; opcode = in.readUnsignedByte())
		{
			switch (opcode)
			{
				case 1:
					in.readUnsignedShort(); // inventory model
					break;
				case 2:
					name = in.readString();
					break;
				case 3:
				case 9:
					in.readString(); // examine / unknown1
					break;
				case 4:
				case 5:
				case 6:
				case 7:
				case 8:
					in.readUnsignedShort(); // 2d zoom/rotation/offsets
					break;
				case 11:
				case 15:
				case 16:
				case 65:
				case 160:
				case 251:
					break; // flag opcodes carry no payload
				case 12:
					in.readInt(); // cost
					break;
				case 13:
					wearPos1 = in.readByte();
					break;
				case 14:
					wearPos2 = in.readByte();
					break;
				case 23:
					maleModel0 = in.readUnsignedShort();
					maleOffset = in.readUnsignedByte();
					break;
				case 24:
					maleModel1 = in.readUnsignedShort();
					break;
				case 25:
					femaleModel0 = in.readUnsignedShort();
					femaleOffset = in.readUnsignedByte();
					break;
				case 26:
					femaleModel1 = in.readUnsignedShort();
					break;
				case 27:
					wearPos3 = in.readByte();
					break;
				case 30:
				case 31:
				case 32:
				case 33:
				case 34:
				case 35:
				case 36:
				case 37:
				case 38:
				case 39:
					in.readString(); // ground / interface actions
					break;
				case 40:
				{
					int count = in.readUnsignedByte();
					colorFind = new short[count];
					colorReplace = new short[count];
					for (int i = 0; i < count; i++)
					{
						colorFind[i] = (short) in.readUnsignedShort();
						colorReplace[i] = (short) in.readUnsignedShort();
					}
					break;
				}
				case 41:
				{
					int count = in.readUnsignedByte();
					textureFind = new short[count];
					textureReplace = new short[count];
					for (int i = 0; i < count; i++)
					{
						textureFind[i] = (short) in.readUnsignedShort();
						textureReplace[i] = (short) in.readUnsignedShort();
					}
					break;
				}
				case 42:
					in.readByte(); // shift-click drop index
					break;
				case 43:
					// Menu subops: group byte, then (index byte, string) pairs
					// terminated by a zero index byte.
					in.readUnsignedByte();
					while (in.readUnsignedByte() != 0)
					{
						in.readString();
					}
					break;
				case 44:
					in.readInt(); // large inventory model
					break;
				case 45:
					maleModel0 = in.readInt();
					maleOffset = in.readUnsignedByte();
					break;
				case 46:
					maleModel1 = in.readInt();
					break;
				case 47:
					maleModel2 = in.readInt();
					break;
				case 48:
					femaleModel0 = in.readInt();
					femaleOffset = in.readUnsignedByte();
					break;
				case 49:
					femaleModel1 = in.readInt();
					break;
				case 50:
					femaleModel2 = in.readInt();
					break;
				case 51:
					maleHead = in.readInt();
					break;
				case 52:
					maleHead2 = in.readInt();
					break;
				case 53:
					femaleHead = in.readInt();
					break;
				case 54:
					femaleHead2 = in.readInt();
					break;
				case 75:
					in.readShort(); // weight
					break;
				case 78:
					maleModel2 = in.readUnsignedShort();
					break;
				case 79:
					femaleModel2 = in.readUnsignedShort();
					break;
				case 90:
					maleHead = in.readUnsignedShort();
					break;
				case 91:
					femaleHead = in.readUnsignedShort();
					break;
				case 92:
					maleHead2 = in.readUnsignedShort();
					break;
				case 93:
					femaleHead2 = in.readUnsignedShort();
					break;
				case 94:
				case 95:
				case 97:
				case 98:
				case 99:
				case 110:
				case 111:
				case 112:
				case 139:
				case 140:
				case 148:
				case 149:
					in.readUnsignedShort(); // category/noted/resize/links
					break;
				case 100:
				case 101:
				case 102:
				case 103:
				case 104:
				case 105:
				case 106:
				case 107:
				case 108:
				case 109:
					in.readUnsignedShort(); // stack count variant
					in.readUnsignedShort();
					break;
				case 113:
				case 114:
					in.readByte(); // ambient / contrast
					break;
				case 115:
					in.readUnsignedByte(); // team
					break;
				case 161:
				{
					int count = in.readUnsignedShort();
					for (int i = 0; i < count; i++)
					{
						in.readUnsignedShort(); // holding whitelist item
					}
					break;
				}
				case 200:
					// EntityOpsLoader.decodeSubOp: byte, byte, string.
					in.readUnsignedByte();
					in.readUnsignedByte();
					in.readString();
					break;
				case 201:
					// decodeConditionalOp: byte, short, short, int, int, string.
					in.readUnsignedByte();
					in.readUnsignedShort();
					in.readUnsignedShort();
					in.readInt();
					in.readInt();
					in.readString();
					break;
				case 202:
					// decodeConditionalSubOp: byte, 3x short, int, int, string.
					in.readUnsignedByte();
					in.readUnsignedShort();
					in.readUnsignedShort();
					in.readUnsignedShort();
					in.readInt();
					in.readInt();
					in.readString();
					break;
				case 249:
					in.skipParams();
					break;
				default:
					throw new IllegalStateException("unknown item opcode " + opcode);
			}
		}

		// Mirror the dumper's wearable filter: only items with a worn model.
		if (maleModel0 == -1 && femaleModel0 == -1)
		{
			return null;
		}

		ModelRepository.Entry entry = new ModelRepository.Entry();
		entry.n = name;
		entry.mo = maleOffset;
		entry.fo = femaleOffset;
		entry.wp1 = wearPos1;
		entry.wp2 = wearPos2;
		entry.wp3 = wearPos3;
		entry.m = new int[]{maleModel0, maleModel1, maleModel2};
		entry.f = new int[]{femaleModel0, femaleModel1, femaleModel2};
		if (maleHead != -1 || maleHead2 != -1)
		{
			entry.hm = new int[]{maleHead, maleHead2};
		}
		if (femaleHead != -1 || femaleHead2 != -1)
		{
			entry.hf = new int[]{femaleHead, femaleHead2};
		}
		entry.cf = colorFind;
		entry.cr = colorReplace;
		entry.tf = textureFind;
		entry.tr = textureReplace;
		return entry;
	}

	// ------------------------------------------------------------------- kits

	static ModelRepository.Entry decodeKit(byte[] data, boolean[] nonSelectableOut)
	{
		Buffer in = new Buffer(data);
		Integer bodyPartId = null;
		int[] models = null;
		int[] chatheads = {-1, -1, -1, -1, -1};
		short[] recolorFind = null;
		short[] recolorReplace = null;
		short[] retextureFind = null;
		short[] retextureReplace = null;

		for (int opcode = in.readUnsignedByte(); opcode != 0; opcode = in.readUnsignedByte())
		{
			if (opcode == 1)
			{
				bodyPartId = in.readUnsignedByte();
			}
			else if (opcode == 2)
			{
				int count = in.readUnsignedByte();
				models = new int[count];
				for (int i = 0; i < count; i++)
				{
					models[i] = in.readUnsignedShort();
				}
			}
			else if (opcode == 3)
			{
				// Flagged non-selectable: character creation never offers this
				// style. No payload.
				nonSelectableOut[0] = true;
			}
			else if (opcode == 5)
			{
				int count = in.readUnsignedByte();
				models = new int[count];
				for (int i = 0; i < count; i++)
				{
					models[i] = in.readInt();
				}
			}
			else if (opcode == 40)
			{
				int count = in.readUnsignedByte();
				recolorFind = new short[count];
				recolorReplace = new short[count];
				for (int i = 0; i < count; i++)
				{
					// NOTE: signed shorts here, unlike items and spotanims.
					recolorFind[i] = (short) in.readShort();
					recolorReplace[i] = (short) in.readShort();
				}
			}
			else if (opcode == 41)
			{
				int count = in.readUnsignedByte();
				retextureFind = new short[count];
				retextureReplace = new short[count];
				for (int i = 0; i < count; i++)
				{
					retextureFind[i] = (short) in.readShort();
					retextureReplace[i] = (short) in.readShort();
				}
			}
			else if (opcode >= 60 && opcode < 70)
			{
				chatheads[opcode - 60] = in.readUnsignedShort();
			}
			else if (opcode >= 70 && opcode < 80)
			{
				chatheads[opcode - 70] = in.readInt();
			}
			else
			{
				throw new IllegalStateException("unknown kit opcode " + opcode);
			}
		}

		// Mirror the dumper's filter: kits without models are unusable.
		if (models == null || models.length == 0)
		{
			return null;
		}

		ModelRepository.Entry entry = new ModelRepository.Entry();
		entry.bp = bodyPartId;
		entry.m = models;
		entry.f = models;
		boolean anyHead = false;
		for (int head : chatheads)
		{
			anyHead |= head != -1;
		}
		if (anyHead)
		{
			entry.ch = chatheads;
		}
		entry.cf = recolorFind;
		entry.cr = recolorReplace;
		entry.tf = retextureFind;
		entry.tr = retextureReplace;
		return entry;
	}

	// -------------------------------------------------------------- spotanims

	private static SpotAnimRepository.Entry decodeSpotAnim(byte[] data)
	{
		Buffer in = new Buffer(data);
		int modelId = 0;
		int animationId = -1;
		int resizeX = 128;
		int resizeY = 128;
		int rotation = 0;
		int ambient = 0;
		int contrast = 0;
		short[] recolorFind = null;
		short[] recolorReplace = null;
		short[] retextureFind = null;
		short[] retextureReplace = null;

		for (int opcode = in.readUnsignedByte(); opcode != 0; opcode = in.readUnsignedByte())
		{
			switch (opcode)
			{
				case 1:
					modelId = in.readUnsignedShort();
					break;
				case 2:
					animationId = in.readUnsignedShort();
					break;
				case 3:
					modelId = in.readInt();
					break;
				case 4:
					resizeX = in.readUnsignedShort();
					break;
				case 5:
					resizeY = in.readUnsignedShort();
					break;
				case 6:
					rotation = in.readUnsignedShort();
					break;
				case 7:
					ambient = in.readUnsignedByte();
					break;
				case 8:
					contrast = in.readUnsignedByte();
					break;
				case 9:
					in.readString(); // debug name
					break;
				case 10:
					// A newer flag opcode with NO payload - proven empirically:
					// the offline dumper's library ignores unknown opcodes
					// without consuming bytes, and every affected definition
					// (39 of them, ids 3882+) still dumped perfectly clean.
					break;
				case 40:
				{
					int count = in.readUnsignedByte();
					recolorFind = new short[count];
					recolorReplace = new short[count];
					for (int i = 0; i < count; i++)
					{
						recolorFind[i] = (short) in.readUnsignedShort();
						recolorReplace[i] = (short) in.readUnsignedShort();
					}
					break;
				}
				case 41:
				{
					int count = in.readUnsignedByte();
					retextureFind = new short[count];
					retextureReplace = new short[count];
					for (int i = 0; i < count; i++)
					{
						retextureFind[i] = (short) in.readUnsignedShort();
						retextureReplace[i] = (short) in.readUnsignedShort();
					}
					break;
				}
				default:
					throw new IllegalStateException("unknown spotanim opcode " + opcode);
			}
		}

		// Mirror the dumper's filter: a spotanim without a model shows nothing.
		if (modelId <= 0)
		{
			return null;
		}

		SpotAnimRepository.Entry entry = new SpotAnimRepository.Entry();
		entry.m = modelId;
		entry.a = animationId;
		entry.rx = resizeX == 128 ? null : resizeX;
		entry.ry = resizeY == 128 ? null : resizeY;
		entry.rot = rotation == 0 ? null : rotation;
		entry.am = ambient == 0 ? null : ambient;
		entry.co = contrast == 0 ? null : contrast;
		entry.cf = recolorFind;
		entry.cr = recolorReplace;
		entry.tf = retextureFind;
		entry.tr = retextureReplace;
		return entry;
	}

	// ----------------------------------------------------------------- buffer

	/** Minimal big-endian reader matching runelite-cache's InputStream widths. */
	private static final class Buffer
	{
		private final byte[] data;
		private int offset;

		Buffer(byte[] data)
		{
			this.data = data;
		}

		int readUnsignedByte()
		{
			return data[offset++] & 0xFF;
		}

		int readByte()
		{
			return data[offset++];
		}

		int readUnsignedShort()
		{
			return (readUnsignedByte() << 8) | readUnsignedByte();
		}

		int readShort()
		{
			return (short) readUnsignedShort();
		}

		int read24BitInt()
		{
			return (readUnsignedByte() << 16) | (readUnsignedByte() << 8) | readUnsignedByte();
		}

		int readInt()
		{
			return (readUnsignedByte() << 24) | (readUnsignedByte() << 16)
				| (readUnsignedByte() << 8) | readUnsignedByte();
		}

		/**
		 * A 0-terminated string. Only item NAMES are kept, and those are
		 * plain CP1252; the special-character remapping the cache library
		 * applies affects codepoints 128-159, which item names do not use -
		 * anything in that range maps through the same table here for parity.
		 */
		String readString()
		{
			StringBuilder sb = new StringBuilder();
			for (int b = readUnsignedByte(); b != 0; b = readUnsignedByte())
			{
				if (b >= 128 && b < 160)
				{
					char mapped = CP1252_SPECIALS[b - 128];
					sb.append(mapped == 0 ? '?' : mapped);
				}
				else
				{
					sb.append((char) b);
				}
			}
			return sb.toString();
		}

		/** Skips a params map: count, then (isString byte, 24-bit key, value). */
		void skipParams()
		{
			int count = readUnsignedByte();
			for (int i = 0; i < count; i++)
			{
				boolean isString = readUnsignedByte() == 1;
				read24BitInt();
				if (isString)
				{
					readString();
				}
				else
				{
					readInt();
				}
			}
		}
	}

	/** Windows-1252's 0x80-0x9F block, as the cache text format defines it. */
	private static final char[] CP1252_SPECIALS = {
		'€', 0, '‚', 'ƒ', '„', '…', '†', '‡',
		'ˆ', '‰', 'Š', '‹', 'Œ', 0, 'Ž', 0,
		0, '‘', '’', '“', '”', '•', '–', '—',
		'˜', '™', 'š', '›', 'œ', 0, 'ž', 'Ÿ',
	};
}

package com.rapidursa.holster.appearance;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.kit.KitType;

/**
 * Holds item and body-kit model mappings parsed from the live game cache.
 *
 * <p>The RuneLite API's {@code ItemComposition} only exposes {@code getInventoryModel()};
 * the worn model ids ({@code maleModel0..2} / {@code femaleModel0..2}) and body kit models
 * live in the cache definitions. This class stores the parsed definitions so
 * Rapid Holster can rebuild wearable item models from cache data.
 */
@Slf4j
@Singleton
public class ModelRepository
{
	/** An item the follower can wear, for the outfit picker. */
	public static class WearableItem
	{
		public final int id;
		public final String name;

		WearableItem(int id, String name)
		{
			this.id = id;
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	public static class Entry
	{
		/** Item name; present in dumps produced by the current dumper. */
		public String n;
		/** Kits only: KitDefinition.bodyPartId, encoding both body part and gender. */
		public Integer bp;
		/** Vertical offsets the client applies to a worn model before merging. */
		public Integer mo;
		public Integer fo;

		/**
		 * Equipment slots this item occupies. wp1 is where it goes; wp2 and wp3 are
		 * further slots it HIDES - a platebody hides the arms kit, a full helm hides
		 * hair and jaw. Indices match KitType.
		 */
		public Integer wp1;
		public Integer wp2;
		public Integer wp3;

		public int offset(int gender)
		{
			Integer chosen = gender == 1 ? fo : mo;
			return chosen == null ? 0 : chosen;
		}
		/** Male worn model ids, -1 for unused. */
		public int[] m;
		/** Female worn model ids, -1 for unused. */
		public int[] f;
		/** Colours to find / replace with. */
		public short[] cf;
		public short[] cr;
		/** Textures to find / replace with. */
		public short[] tf;
		public short[] tr;

		public int[] models(int gender)
		{
			int[] chosen = gender == 1 ? f : m;
			if (chosen == null || chosen.length == 0)
			{
				chosen = gender == 1 ? m : f;
			}
			return chosen;
		}

		/**
		 * Chathead models: items carry male/female dialogue-head variants, kits
		 * carry KitDefinition.chatheadModels. These are the separate models real
		 * dialogs animate, with their own talk-animation skeletons.
		 */
		public int[] hm;
		public int[] hf;
		public int[] ch;

		/** The dialogue-head models for this entry, or null if it has none. */
		public int[] headModels(int gender)
		{
			if (ch != null)
			{
				return ch;
			}
			int[] chosen = gender == 1 ? hf : hm;
			if (chosen == null)
			{
				chosen = gender == 1 ? hm : hf;
			}
			return chosen;
		}
	}

	@Getter
	private volatile boolean loaded;

	@Getter
	private volatile String status = "not loaded";

	private volatile Map<String, Entry> items = Collections.emptyMap();
	private volatile Map<String, Entry> kits = Collections.emptyMap();

	/**
	 * Builds the catalogue from the client's own loaded cache.
	 * No-op while the cache indexes are not available yet; callers retry.
	 */
	public void loadFromClient(net.runelite.api.Client client)
	{
		Map<String, Entry> liveItems = LiveCacheParser.parseItems(client);
		if (liveItems.isEmpty())
		{
			return;
		}
		items = liveItems;
		kits = LiveCacheParser.parseKits(client);
		loaded = true;
		status = items.size() + " items, " + kits.size() + " kits (live cache)";
		log.info("Loaded model catalogue from live cache: {}", status);
	}

	public void unload()
	{
		items = Collections.emptyMap();
		kits = Collections.emptyMap();
		loaded = false;
		status = "not loaded";
	}

	public Entry item(int itemId)
	{
		return items.get(Integer.toString(itemId));
	}

	/** Name of a dumped item, or null if this dump predates name support. */
	public String itemName(int itemId)
	{
		Entry entry = item(itemId);
		return entry == null ? null : entry.n;
	}

	/**
	 * Every wearable item whose name matches {@code query}, sorted by name. The dump
	 * contains exactly the items that have worn models, so this is the complete set
	 * of things the follower can actually be dressed in.
	 */
	public List<WearableItem> search(String query, int limit)
	{
		String needle = query == null ? "" : query.trim().toLowerCase(java.util.Locale.ROOT);
		List<WearableItem> matches = new ArrayList<>();

		for (Map.Entry<String, Entry> entry : items.entrySet())
		{
			String name = entry.getValue().n;
			if (name == null || name.isEmpty() || "null".equals(name))
			{
				continue;
			}
			if (!needle.isEmpty() && !name.toLowerCase(java.util.Locale.ROOT).contains(needle))
			{
				continue;
			}

			try
			{
				matches.add(new WearableItem(Integer.parseInt(entry.getKey()), name));
			}
			catch (NumberFormatException ignored)
			{
				// Malformed key in the dump; skip it.
			}

			if (matches.size() >= limit * 4)
			{
				break;
			}
		}

		matches.sort((a, b) ->
		{
			// Exact and prefix matches first, then alphabetical.
			boolean ap = a.name.toLowerCase(java.util.Locale.ROOT).startsWith(needle);
			boolean bp = b.name.toLowerCase(java.util.Locale.ROOT).startsWith(needle);
			if (ap != bp)
			{
				return ap ? -1 : 1;
			}
			return a.name.compareToIgnoreCase(b.name);
		});

		return matches.size() > limit ? matches.subList(0, limit) : matches;
	}

	/**
	 * Body parts in bodyPartId order. The id is this index for a male kit, and this
	 * index + 7 for a female one - verified against the whole dump, which is
	 * symmetric across the two halves.
	 */
	private static final KitType[] BODY_PART_ORDER = {
		KitType.HAIR, KitType.JAW, KitType.TORSO, KitType.ARMS,
		KitType.HANDS, KitType.LEGS, KitType.BOOTS,
	};

	private static final int PARTS_PER_GENDER = BODY_PART_ORDER.length;

	/** @return the bodyPartId a kit must have to belong to this slot and gender. */
	public static int bodyPartId(KitType part, int gender)
	{
		for (int i = 0; i < BODY_PART_ORDER.length; i++)
		{
			if (BODY_PART_ORDER[i] == part)
			{
				return i + (gender == 1 ? PARTS_PER_GENDER : 0);
			}
		}
		return -1;
	}

	/**
	 * Kit ids the cache flags non-selectable - the styles character creation
	 * never offers. Read from the live cache; empty until that lands.
	 */
	private volatile java.util.Set<Integer> nonSelectableKits = Collections.emptySet();

	public void setNonSelectableKits(java.util.Set<Integer> ids)
	{
		nonSelectableKits = ids == null ? Collections.emptySet() : ids;
	}

	/**
	 * Every kit the picker should offer for one body part and gender, sorted
	 * by id. Two filters make this the list a player recognises rather than a
	 * raw cache listing:
	 *
	 * <ul>
	 *   <li>kits flagged non-selectable are dropped - those are the NPC-only
	 *   and unreleased styles character creation hides;</li>
	 *   <li>kits whose models and chatheads are byte-identical to an earlier
	 *   one are dropped - the cache holds several such pairs (33/35 hands,
	 *   43/44 boots, 141/142/152 female hair, ...) which rendered as
	 *   duplicate entries that looked and behaved identically.</li>
	 * </ul>
	 */
	public List<Integer> kitsFor(KitType part, int gender)
	{
		int wanted = bodyPartId(part, gender);
		List<Integer> ids = new ArrayList<>();
		if (wanted < 0)
		{
			return ids;
		}

		for (Map.Entry<String, Entry> entry : kits.entrySet())
		{
			Integer bodyPart = entry.getValue().bp;
			if (bodyPart == null || bodyPart != wanted)
			{
				continue;
			}
			try
			{
				int id = Integer.parseInt(entry.getKey());
				if (!nonSelectableKits.contains(id))
				{
					ids.add(id);
				}
			}
			catch (NumberFormatException ignored)
			{
				// Malformed key; skip.
			}
		}

		ids.sort(Integer::compareTo);

		List<Integer> distinct = new ArrayList<>(ids.size());
		java.util.Set<String> seen = new java.util.HashSet<>();
		for (int id : ids)
		{
			if (seen.add(appearanceSignature(kits.get(Integer.toString(id)))))
			{
				distinct.add(id);
			}
		}
		return distinct;
	}

	/** What the kit actually looks like: identical signatures render identically. */
	private static String appearanceSignature(Entry entry)
	{
		if (entry == null)
		{
			return "null";
		}
		return java.util.Arrays.toString(entry.m)
			+ java.util.Arrays.toString(entry.ch)
			+ java.util.Arrays.toString(entry.cf)
			+ java.util.Arrays.toString(entry.cr)
			+ java.util.Arrays.toString(entry.tf)
			+ java.util.Arrays.toString(entry.tr);
	}

	/** True if the dump carries body-part metadata (older dumps do not). */
	public boolean hasKitParts()
	{
		for (Entry e : kits.values())
		{
			return e.bp != null;
		}
		return false;
	}

	/** Every wearable item id in the dump. */
	public List<Integer> allItemIds()
	{
		List<Integer> ids = new ArrayList<>(items.size());
		for (String key : items.keySet())
		{
			try
			{
				ids.add(Integer.parseInt(key));
			}
			catch (NumberFormatException ignored)
			{
				// Malformed key; skip.
			}
		}
		return ids;
	}

	public boolean hasNames()
	{
		for (Entry e : items.values())
		{
			return e.n != null;
		}
		return false;
	}

	public Entry kit(int kitId)
	{
		return kits.get(Integer.toString(kitId));
	}

	public boolean hasItem(int itemId)
	{
		return items.containsKey(Integer.toString(itemId));
	}
}

package com.rapidursa.holster.appearance;

import java.util.Collections;
import java.util.Map;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * The spotanim ("graphic") catalogue parsed from the live game cache. A
 * spotanim is how the game shows teleport swirls, spell
 * impacts and the home teleport's rune circle: a model, the animation that
 * plays it once, scaling, rotation, recolours and lighting tweaks.
 *
 * <p>{@code Actor.getGraphic()} exposes the active id; the parsed definition
 * supplies the corresponding model and animation data.
 */
@Slf4j
@Singleton
public class SpotAnimRepository
{
	/** One spotanim definition. Field names mirror the dumper's. */
	public static class Entry
	{
		public int m;
		public int a;
		public Integer rx;
		public Integer ry;
		public Integer rot;
		public Integer am;
		public Integer co;
		public short[] cf;
		public short[] cr;
		public short[] tf;
		public short[] tr;

		public int modelId()
		{
			return m;
		}

		public int animationId()
		{
			return a;
		}

		public int resizeX()
		{
			return rx == null ? 128 : rx;
		}

		public int resizeY()
		{
			return ry == null ? 128 : ry;
		}

		public int rotation()
		{
			return rot == null ? 0 : rot;
		}

		public int ambient()
		{
			return am == null ? 0 : am;
		}

		public int contrast()
		{
			return co == null ? 0 : co;
		}
	}

	private Map<String, Entry> spotanims = Collections.emptyMap();

	@Getter
	private String status = "not loaded";

	/**
	 * Builds the catalogue from the client's own loaded cache. No-op
	 * while the cache indexes are not available yet; callers retry.
	 */
	public void loadFromClient(net.runelite.api.Client client)
	{
		Map<String, Entry> live = LiveCacheParser.parseSpotAnims(client);
		if (live.isEmpty())
		{
			return;
		}
		spotanims = live;
		status = spotanims.size() + " spotanims (live cache)";
		log.info("Loaded {} spotanims from live cache", spotanims.size());
	}

	/** The definition for a graphic id, or null if unknown or not loaded. */
	public Entry get(int graphicId)
	{
		return spotanims.get(Integer.toString(graphicId));
	}

	public boolean isLoaded()
	{
		return !spotanims.isEmpty();
	}
}

